"""
generate_fixed_figures_STANDALONE.py
====================================
Self-contained launcher for the corrected Settling/JMLR Figures 2, 4, and 12.

This version embeds the exact recovered environment.py, energy.py, inference.py,
and figures_fixed.py source used by the original figure package, so it does not
require those modules to be copied separately next to this file.

Outputs are FORCE-SAVED to a "figures" folder next to this script.\nOn Windows, the folder is opened automatically after successful generation.
Required third-party packages: numpy, matplotlib, scipy.
"""
from pathlib import Path
import sys
import types
import os



def _install_module(name: str, source: str, fake_file: str):
    module = types.ModuleType(name)
    module.__file__ = fake_file
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(source, fake_file, "exec"), module.__dict__)
    return module


def main():
    # Robust Windows/PyCharm path handling.
    # With PyDev runfile(..., wdir=...), __file__ should point to this script.
    # If it does not, fall back to the current working directory.
    try:
        here = Path(__file__).resolve().parent
    except NameError:
        here = Path.cwd().resolve()

    output_dir = here / "figures"
    output_dir.mkdir(parents=True, exist_ok=True)

    print("=" * 72)
    print("Settling figure generator")
    print(f"Python executable : {sys.executable}")
    print(f"Working directory : {Path.cwd().resolve()}")
    print(f"Script directory  : {here}")
    print(f"OUTPUT DIRECTORY  : {output_dir}")
    print("=" * 72)

    # Verify Windows/filesystem write access before doing any computation.
    probe = output_dir / "_write_test.tmp"
    try:
        probe.write_text("write test OK", encoding="utf-8")
        probe.unlink(missing_ok=True)
    except Exception as exc:
        raise RuntimeError(
            f"Cannot write to output folder: {output_dir}\n"
            f"Reason: {exc}"
        ) from exc

    fake_code_dir = here / "code"
    _environment_source = '"""\nenvironment.py\n==============\nDouble-Bifurcation Environment (from bebV3.py, analytically extended).\n\nTwo circular obstacles positioned symmetrically at x = ±0.4, y = 0.\nThis creates the canonical non-convex validity structure:\n\n  Valid Mode A (upper):  trajectory arcs ABOVE both obstacles  →  y > 0.3\n  Valid Mode B (lower):  trajectory arcs BELOW both obstacles  →  y < -0.3\n  Conditional Mean:      arithmetic mean ≈ y = 0              →  COLLISION\n\nThis is the geometric instantiation of Conditional Mean Collapse (Theorem 1).\n\nObstacle geometry inherits bebV3.py:\n  radius = 0.25, safety margin = 0.05\n  World:   x ∈ [-1, 1],  y ∈ [-1, 1]\n  Start:   (-1, 0)\n  Goal:    ( 1, 0)\n"""\n\nimport numpy as np\n\n# ── Constants ────────────────────────────────────────────────────────────────\nSEQ_LEN       = 40\nOBS_RADIUS    = 0.25\nSAFETY_MARGIN = 0.05\nOBS_R         = OBS_RADIUS + SAFETY_MARGIN   # effective constraint radius\n\nSTART = np.array([-1.0, 0.0])\nGOAL  = np.array([ 1.0, 0.0])\n\n# Fixed test-time obstacle centres (obs1_y = obs2_y = 0 → symmetric, from bebV3)\nOBS_CENTRES = np.array([[-0.4, 0.0],   # left obstacle\n                         [ 0.4, 0.0]])  # right obstacle\n\nCOLORS = {\n    "attention": "#1F77B4",   # standard scientific blue\n    "diffusion":  "#FF7F0E",  # standard scientific orange\n    "ebm":        "#9467BD",  # standard scientific purple\n    "settling":   "#2CA02C",  # standard scientific green\n    "proposal":   "#7F7F7F",  # neutral gray\n    "core":       "#333333",  # dark charcoal (obstacle body)\n    "margin":     "#D9D9D9",  # light silver (safety margin)\n    "upper":      "#D62728",  # mode A (red)\n    "lower":      "#17BECF",  # mode B (teal)\n    "mean":       "#8C564B",  # conditional mean (brown/invalid)\n}\n\n\n# ── Trajectory generators ────────────────────────────────────────────────────\n\ndef _make_x(n: int = SEQ_LEN) -> np.ndarray:\n    return np.linspace(-1.0, 1.0, n)\n\n\ndef _bump(x: np.ndarray, cx: float, sigma: float, amp: float) -> np.ndarray:\n    """Gaussian bump centred at cx."""\n    return amp * np.exp(-((x - cx) / sigma) ** 2)\n\n\ndef upper_trajectory(n: int = SEQ_LEN, amp: float = 0.72) -> np.ndarray:\n    """\n    Valid Mode A — arcs above both obstacles.\n    y(x) = G(-0.4) + G(+0.4) with positive amplitude.\n    """\n    x = _make_x(n)\n    y = _bump(x, -0.4, 0.38, amp) + _bump(x, 0.4, 0.38, amp)\n    return np.column_stack([x, y])\n\n\ndef lower_trajectory(n: int = SEQ_LEN, amp: float = 0.72) -> np.ndarray:\n    """\n    Valid Mode B — arcs below both obstacles (negated upper).\n    """\n    t = upper_trajectory(n, amp)\n    return np.column_stack([t[:, 0], -t[:, 1]])\n\n\ndef mean_trajectory(n: int = SEQ_LEN) -> np.ndarray:\n    """\n    Conditional mean of upper and lower modes.\n    Arithmetic mean → y ≡ 0.0 → passes through both obstacle centres.\n    This is the INVALID trajectory demonstrating Conditional Mean Collapse.\n    """\n    u = upper_trajectory(n)\n    l = lower_trajectory(n)\n    return 0.5 * (u + l)           # y = 0 everywhere\n\n\n# ── Obstacle geometry ────────────────────────────────────────────────────────\n\ndef obstacle_sdf(points: np.ndarray,\n                 obs: np.ndarray = OBS_CENTRES) -> np.ndarray:\n    """\n    Signed distance field for circular obstacle union.\n    Returns min SDF over all obstacles:\n      positive → outside (safe)\n      negative → inside (collision)\n\n    points: (N, 2)\n    returns: (N,)\n    """\n    sdfs = []\n    for cx, cy in obs:\n        d = np.sqrt((points[:, 0] - cx)**2 + (points[:, 1] - cy)**2) - OBS_RADIUS\n        sdfs.append(d)\n    return np.minimum(*sdfs) if len(sdfs) > 1 else sdfs[0]\n\n\ndef is_collision_free(traj: np.ndarray,\n                      obs: np.ndarray = OBS_CENTRES,\n                      margin: float = 0.02) -> bool:\n    """True if every waypoint clears all obstacles by at least margin."""\n    for cx, cy in obs:\n        dists = np.sqrt((traj[:, 0] - cx)**2 + (traj[:, 1] - cy)**2)\n        if np.any(dists < OBS_RADIUS + margin):\n            return False\n    return True\n\n\ndef min_clearance(traj: np.ndarray,\n                  obs: np.ndarray = OBS_CENTRES) -> float:\n    """Minimum clearance from any obstacle across the trajectory."""\n    min_d = np.inf\n    for cx, cy in obs:\n        dists = np.sqrt((traj[:, 0] - cx)**2 + (traj[:, 1] - cy)**2) - OBS_RADIUS\n        min_d = min(min_d, float(dists.min()))\n    return min_d\n\n\ndef trajectory_smoothness(traj: np.ndarray) -> float:\n    """Mean squared second differences — lower is smoother."""\n    d2 = traj[2:] - 2*traj[1:-1] + traj[:-2]\n    return float(np.mean(d2**2))\n\n\n# ── Randomised evaluation contexts ──────────────────────────────────────────\n\ndef random_context(rng: np.random.Generator,\n                   obs_jitter: float = 0.1) -> np.ndarray:\n    """\n    Randomised obstacle centres for quantitative evaluation.\n    Jitters around the symmetric (test-time) configuration.\n    """\n    base = OBS_CENTRES.copy()\n    base[:, 1] += rng.uniform(-obs_jitter, obs_jitter, 2)\n    return base\n'
    environment_module = _install_module("environment", _environment_source, str(fake_code_dir / "environment.py"))
    _energy_source = '"""\nenergy.py\n=========\nComposite energy E_total and analytical gradients for settling dynamics.\n\nE_total(s, c) = λ_obs  · E_obstacle(s, c)      ← non-convex constraint (Eq. 14)\n              + λ_prop · ‖s − π_φ(c)‖²          ← proposal anchoring  (Eq. 18)\n              + λ_sm   · R_smooth(s)              ← curvature regularization\n\nAll gradients are computed analytically to ensure stability.\nThe Laplacian gradient uses the bilaplacian formula (L^T L).\n"""\n\nimport numpy as np\nfrom environment import OBS_RADIUS, SAFETY_MARGIN, START, GOAL\n\nOBS_R = OBS_RADIUS + SAFETY_MARGIN\n\n\n# ── Obstacle energy (smooth barrier) ────────────────────────────────────────\n\ndef obstacle_energy(traj: np.ndarray,\n                    obs_centres: np.ndarray,\n                    lam: float = 80.0,\n                    r: float = OBS_R) -> float:\n    """\n    E_obs = λ Σ_i Σ_j max(0, r − dist(s_i, obs_j))²\n\n    Smooth ReLU-squared barrier — zero outside obstacle margin,\n    quadratically increasing inside.  Provides non-convex validity structure.\n    """\n    E = 0.0\n    for cx, cy in obs_centres:\n        dx = traj[:, 0] - cx\n        dy = traj[:, 1] - cy\n        dist = np.sqrt(dx**2 + dy**2 + 1e-8)\n        viol = np.maximum(0.0, r - dist)\n        E += lam * np.sum(viol**2)\n    return E\n\n\ndef obstacle_gradient(traj: np.ndarray,\n                      obs_centres: np.ndarray,\n                      lam: float = 80.0,\n                      r: float = OBS_R) -> np.ndarray:\n    """Analytical gradient of E_obs w.r.t. traj waypoints."""\n    grad = np.zeros_like(traj)\n    for cx, cy in obs_centres:\n        dx = traj[:, 0] - cx\n        dy = traj[:, 1] - cy\n        dist = np.sqrt(dx**2 + dy**2 + 1e-8)\n        viol = np.maximum(0.0, r - dist)\n        # ∂E/∂traj_i = -2λ · viol_i · (traj_i − obs) / dist_i\n        factor = -2.0 * lam * viol / dist\n        grad[:, 0] += factor * dx\n        grad[:, 1] += factor * dy\n    return grad\n\n\n# ── Smoothness energy (Laplacian / curvature) ────────────────────────────────\n\ndef smooth_energy(traj: np.ndarray, lam: float = 8.0) -> float:\n    """\n    R_smooth = λ Σ_i ‖s_{i+2} − 2s_{i+1} + s_i‖²\n\n    Second-order finite differences penalise curvature.\n    High λ forces the trajectory to be a near-polynomial curve,\n    eliminating zigzagging artefacts.\n    """\n    d2 = traj[2:] - 2*traj[1:-1] + traj[:-2]\n    return lam * float(np.sum(d2**2))\n\n\ndef smooth_gradient(traj: np.ndarray, lam: float = 8.0) -> np.ndarray:\n    """\n    Analytical gradient of R_smooth (bilaplacian operator L^T L).\n\n    ∂R_smooth/∂s_i = 2λ (d2[i−2] − 2·d2[i−1] + d2[i])\n    where d2[k] = s_{k+2} − 2s_{k+1} + s_k.\n    """\n    N = traj.shape[0]\n    d2 = traj[2:] - 2*traj[1:-1] + traj[:-2]       # (N-2, 2)\n    d2_ext = np.zeros((N, 2))\n    d2_ext[1:N-1] = d2                               # zero-pad boundaries\n\n    # Bilaplacian: d4[i] = d2[i] - 2*d2[i-1] + d2[i-2]\n    d4 = np.zeros_like(traj)\n    for i in range(1, N-1):\n        v = np.zeros(2)\n        if 0 <= i <= N-3:      v  += d2_ext[i]\n        if 0 <= i-1 <= N-3:    v  -= 2 * d2_ext[i-1]\n        if 0 <= i-2 <= N-3:    v  += d2_ext[i-2]\n        d4[i] = v\n    return 2.0 * lam * d4\n\n\n# ── Proposal anchoring energy ────────────────────────────────────────────────\n\ndef anchor_energy(traj: np.ndarray, proposal: np.ndarray,\n                  lam: float = 0.4) -> float:\n    """\n    λ_p ‖s − π_φ(c)‖² — prevents convergence to context-irrelevant equilibria.\n    Provides semantic coherence with the (possibly invalid) proposal.\n    """\n    diff = traj - proposal\n    return lam * float(np.sum(diff**2))\n\n\ndef anchor_gradient(traj: np.ndarray, proposal: np.ndarray,\n                    lam: float = 0.4) -> np.ndarray:\n    return 2.0 * lam * (traj - proposal)\n\n\n# ── Endpoint pinning ─────────────────────────────────────────────────────────\n\ndef endpoint_energy(traj: np.ndarray, lam: float = 50.0) -> float:\n    e  = lam * float(np.sum((traj[0]  - START)**2))\n    e += lam * float(np.sum((traj[-1] - GOAL)**2))\n    return e\n\n\ndef endpoint_gradient(traj: np.ndarray, lam: float = 50.0) -> np.ndarray:\n    grad = np.zeros_like(traj)\n    grad[0]  = 2.0 * lam * (traj[0]  - START)\n    grad[-1] = 2.0 * lam * (traj[-1] - GOAL)\n    return grad\n\n\n# ── Total energy + gradient ──────────────────────────────────────────────────\n\ndef total_energy(traj: np.ndarray,\n                 proposal: np.ndarray,\n                 obs_centres: np.ndarray,\n                 lam_obs: float = 80.0,\n                 lam_smooth: float = 8.0,\n                 lam_anchor: float = 0.4,\n                 lam_end: float = 50.0) -> float:\n    """E_total = E_obs + R_smooth + E_anchor + E_endpoints"""\n    return (obstacle_energy(traj, obs_centres, lam_obs)\n          + smooth_energy(traj, lam_smooth)\n          + anchor_energy(traj, proposal, lam_anchor)\n          + endpoint_energy(traj, lam_end))\n\n\ndef total_gradient(traj: np.ndarray,\n                   proposal: np.ndarray,\n                   obs_centres: np.ndarray,\n                   lam_obs: float = 80.0,\n                   lam_smooth: float = 8.0,\n                   lam_anchor: float = 0.4,\n                   lam_end: float = 50.0) -> np.ndarray:\n    """Analytical gradient ∇_s E_total."""\n    return (obstacle_gradient(traj, obs_centres, lam_obs)\n          + smooth_gradient(traj, lam_smooth)\n          + anchor_gradient(traj, proposal, lam_anchor)\n          + endpoint_gradient(traj, lam_end))\n'
    energy_module = _install_module("energy", _energy_source, str(fake_code_dir / "energy.py"))
    _inference_source = '"""\ninference.py\n============\nFour inference paradigms — using control-point spline parameterization\nfor SettlingInferenceModule to guarantee smooth, zigzag-free trajectories.\n\n  A. Attention / Mean-Seeking  — convex aggregation → Conditional Mean Collapse\n  B. Diffusion / Stochastic    — noisy denoising → inconsistent\n  C. EBM / Direct Optimization — gradient descent from random init → stagnation\n  D. SettlingInferenceModule   — equilibrium selection, smooth by construction\n"""\n\nimport numpy as np\nfrom scipy.ndimage import gaussian_filter1d\nfrom scipy.interpolate import CubicSpline\nfrom environment import (SEQ_LEN, START, GOAL, OBS_CENTRES, OBS_R,\n                          upper_trajectory, lower_trajectory, mean_trajectory,\n                          OBS_RADIUS, SAFETY_MARGIN, _bump)\nfrom energy import obstacle_energy, obstacle_gradient, endpoint_energy, endpoint_gradient\n\n\n# ── Control-point spline helpers ─────────────────────────────────────────────\n\n_X_CP = np.array([-1.0, -0.65, -0.4, 0.0, 0.4, 0.65, 1.0])  # 7 control points\n_X_DENSE = np.linspace(-1.0, 1.0, SEQ_LEN)\n\n\ndef traj_from_cp(y_cp: np.ndarray,\n                 x_cp: np.ndarray = _X_CP,\n                 n_dense: int = SEQ_LEN) -> np.ndarray:\n    """\n    Cubic spline from y-control-points → dense smooth trajectory.\n    C2-smooth by construction: eliminates zigzagging at the parameterisation level.\n    """\n    x_dense = np.linspace(x_cp[0], x_cp[-1], n_dense)\n    cs = CubicSpline(x_cp, y_cp, bc_type=\'clamped\')\n    y_dense = cs(x_dense)\n    return np.column_stack([x_dense, y_dense])\n\n\ndef cp_gradient(y_cp: np.ndarray,\n                obs_centres: np.ndarray,\n                lam_obs: float = 80.0,\n                eps: float = 1e-4) -> np.ndarray:\n    """\n    Numerical gradient of E_obstacle w.r.t. interior control-point y-values.\n    Only interior points (indices 1..-1) are optimised; endpoints are pinned.\n    Cost: 2*(N_CP-2) energy evaluations per step — very cheap.\n    """\n    n = len(y_cp)\n    grad = np.zeros(n)\n    for i in range(1, n - 1):       # skip fixed endpoints\n        yp = y_cp.copy(); yp[i] += eps\n        ym = y_cp.copy(); ym[i] -= eps\n        Ep = obstacle_energy(traj_from_cp(yp), obs_centres, lam_obs)\n        Em = obstacle_energy(traj_from_cp(ym), obs_centres, lam_obs)\n        grad[i] = (Ep - Em) / (2 * eps)\n    return grad\n\n\n# ── A. Attention / Mean-Seeking ──────────────────────────────────────────────\n\ndef attention_inference(context: np.ndarray = OBS_CENTRES,\n                        n: int = SEQ_LEN) -> np.ndarray:\n    """\n    Expectation-based (attention-like) inference.\n\n    Under MSE training with symmetric bimodal data, the Bayes-optimal\n    predictor is the conditional mean (Theorem 1):\n\n        f*(c) = E[y|c] = 0.5·y_A + 0.5·y_B = 0  (symmetric context)\n\n    Output: y ≡ 0 → passes through both obstacle centres → INVALID.\n    This is a provably structural failure, not a capacity issue.\n    """\n    u = upper_trajectory(n)\n    l = lower_trajectory(n)\n    return 0.5 * (u + l)          # arithmetic mean → y = 0 everywhere\n\n\n# ── B. Diffusion / Stochastic Baseline ───────────────────────────────────────\n\ndef diffusion_inference(context: np.ndarray = OBS_CENTRES,\n                        n: int = SEQ_LEN,\n                        n_steps: int = 120,\n                        noise_init: float = 0.9,\n                        noise_decay: float = 0.94,\n                        step_size: float = 0.04,\n                        rng: np.random.Generator = None) -> dict:\n    """\n    Stochastic denoising baseline. Noise persists throughout inference —\n    the defining feature that distinguishes diffusion from Settling.\n    Shows: stochasticity, non-determinism, inconsistent convergence.\n    """\n    if rng is None:\n        rng = np.random.default_rng(999)\n\n    x_base = np.linspace(-1.0, 1.0, n)\n    s = rng.normal(0, noise_init, (n, 2))\n    s[:, 0] = x_base\n    s[0] = START; s[-1] = GOAL\n\n    history = [(0, s.copy())]\n    energy_curve = [(0, float(obstacle_energy(s, context)))]\n    current_noise = noise_init * 0.45\n\n    for k in range(1, n_steps + 1):\n        # Smooth denoising step\n        s_new = s.copy()\n        s_new[:, 1] = gaussian_filter1d(s[:, 1], sigma=1.8)\n\n        # Obstacle + endpoint gradient (stochastic)\n        g_obs = obstacle_gradient(s_new, context, lam=25.0)\n        g_end = endpoint_gradient(s_new, lam=30.0)\n        s_new -= step_size * (g_obs + g_end)\n\n        # Persistent noise — what makes diffusion stochastic\n        noise = rng.normal(0, current_noise, (n, 2))\n        noise[:, 0] = 0; noise[0] = noise[-1] = 0\n        s_new += noise\n        current_noise *= noise_decay\n\n        s_new[0] = START; s_new[-1] = GOAL\n        s = s_new\n\n        if k % 10 == 0:\n            history.append((k, s.copy()))\n            energy_curve.append((k, float(obstacle_energy(s, context))))\n\n    history.append((n_steps, s.copy()))\n    energy_curve.append((n_steps, float(obstacle_energy(s, context))))\n    return {\'trajectory\': s, \'history\': history, \'energy_curve\': energy_curve}\n\n\n# ── C. EBM / Direct Optimization ─────────────────────────────────────────────\n\ndef ebm_inference(context: np.ndarray = OBS_CENTRES,\n                  n: int = SEQ_LEN,\n                  n_steps: int = 200,\n                  lr: float = 0.008,\n                  rng: np.random.Generator = None) -> dict:\n    """\n    EBM: gradient descent on obstacle energy from RANDOM initialisation.\n    No proposal anchoring → context-irrelevant equilibria, local trapping.\n    """\n    if rng is None:\n        rng = np.random.default_rng(77)\n\n    x_base = np.linspace(-1.0, 1.0, n)\n    s = rng.normal(0, 0.4, (n, 2))\n    s[:, 0] = x_base\n    s[0] = START; s[-1] = GOAL\n\n    history = [(0, s.copy())]\n    energy_curve = [(0, float(obstacle_energy(s, context)))]\n\n    for k in range(1, n_steps + 1):\n        g_obs = obstacle_gradient(s, context, lam=80.0)\n        g_end = endpoint_gradient(s, lam=50.0)\n        # Light smoothness only\n        from energy import smooth_gradient\n        g_sm  = smooth_gradient(s, lam=2.0)\n        grad  = g_obs + g_end + g_sm\n\n        gnorm = np.linalg.norm(grad)\n        if gnorm > 3.0:\n            grad = grad / gnorm * 3.0\n\n        s = s - lr * grad\n        s[0] = START; s[-1] = GOAL\n\n        if k % 25 == 0:\n            history.append((k, s.copy()))\n            energy_curve.append((k, float(obstacle_energy(s, context))))\n\n    # Post-smooth\n    s[:, 1] = gaussian_filter1d(s[:, 1], sigma=2.0)\n    s[0] = START; s[-1] = GOAL\n\n    history.append((n_steps, s.copy()))\n    energy_curve.append((n_steps, float(obstacle_energy(s, context))))\n    return {\'trajectory\': s, \'history\': history, \'energy_curve\': energy_curve}\n\n\n# ── D. SettlingInferenceModule ────────────────────────────────────────────────\n\nclass SettlingInferenceModule:\n    """\n    Settling-Based Inference (SBI) — Section III of the paper.\n\n    Three-component decomposition:\n      Module I   — Proposal π_φ(c):  mean-seeking, analytically y=0\n      Module II  — Energy E(s,c):    obstacle barrier (non-convex validity)\n      Module III — Dynamics:          s^{k+1} = s^k − η ∇_s E  (Eq. 16)\n\n    Key innovation over bebV3.BicameralEnergyBlock:\n      • Control-point parameterisation → smooth by construction (no zigzag)\n      • Cubic spline interpolation → C2-smooth output\n      • Strong bifurcation: large noise (σ=0.30) + weak anchor + strong obstacle\n      • Gradient clipping in GLOBAL (not per-waypoint) sense\n    """\n\n    def __init__(self,\n                 lam_obs:    float = 80.0,\n                 lam_anchor: float = 0.05,   # very weak — let settling be free\n                 x_cp:       np.ndarray = None):\n        self.lam_obs    = lam_obs\n        self.lam_anchor = lam_anchor\n        self.x_cp = x_cp if x_cp is not None else _X_CP.copy()\n\n    # ── Module I: Proposal ───────────────────────────────────────────────\n\n    def proposal(self, context: np.ndarray = OBS_CENTRES,\n                 n: int = SEQ_LEN) -> np.ndarray:\n        """\n        π_φ(c): conditional mean — intentionally invalid.\n        Analytically: y = 0.5*y_A + 0.5*y_B = 0 for symmetric context.\n        This is the saddle point that settling must escape.\n        """\n        return mean_trajectory(n)\n\n    def proposal_cp(self) -> np.ndarray:\n        """Control-point representation of the conditional mean (all zeros)."""\n        return np.zeros(len(self.x_cp))     # y = 0 → invalid conditional mean\n\n    # ── Module III: Settling Dynamics (control-point space) ──────────────\n\n    def settle(self, context: np.ndarray = OBS_CENTRES,\n               n: int = SEQ_LEN,\n               n_steps: int = 100,\n               lr: float = 0.025,\n               noise_std: float = 0.30,\n               rng: np.random.Generator = None,\n               record_every: int = 5) -> dict:\n        """\n        Core settling loop in control-point space.\n\n        s^{(0)} = π_φ(c) + ε,   ε ~ N(0, σ²)   (Algorithm 1, line 1)\n        s^{(k+1)} = s^{(k)} − η ∇_{s_cp} E_obstacle(traj(s_cp), c)\n\n        Working in control-point space (7 parameters) instead of full\n        trajectory space (80 parameters) gives:\n          • Smoothness by construction (cubic spline interpolation)\n          • No Laplacian regularisation needed\n          • Faster, more stable optimisation\n          • No zigzag artefacts possible\n        """\n        if rng is None:\n            rng = np.random.default_rng(42)\n\n        # Initialise: proposal (y=0) + symmetry-breaking noise ε\n        y_cp = self.proposal_cp()\n        y_cp[1:-1] += rng.normal(0, noise_std, len(self.x_cp) - 2)\n        y_cp[0] = y_cp[-1] = 0.0          # hard-pin endpoints\n\n        y_cp_proposal = y_cp.copy()        # for anchoring\n\n        history = [(0, traj_from_cp(y_cp, self.x_cp, n))]\n        energy_curve = [(0, obstacle_energy(traj_from_cp(y_cp, self.x_cp, n),\n                                            context, self.lam_obs))]\n\n        for k in range(1, n_steps + 1):\n            # Obstacle energy gradient w.r.t. control points\n            g_obs = cp_gradient(y_cp, context, self.lam_obs)\n\n            # Very weak anchor: allow settling to explore freely\n            g_anchor = 2.0 * self.lam_anchor * (y_cp - y_cp_proposal)\n\n            grad = g_obs + g_anchor\n            grad[0] = grad[-1] = 0.0      # keep endpoints fixed\n\n            # Global gradient norm clipping\n            gnorm = np.linalg.norm(grad)\n            if gnorm > 2.0:\n                grad = grad * 2.0 / gnorm\n\n            y_cp = y_cp - lr * grad\n            y_cp[0] = y_cp[-1] = 0.0      # pin endpoints\n\n            if k % record_every == 0 or k == n_steps:\n                traj = traj_from_cp(y_cp, self.x_cp, n)\n                history.append((k, traj.copy()))\n                energy_curve.append((k, obstacle_energy(traj, context, self.lam_obs)))\n\n        # Final dense smooth trajectory\n        final_traj = traj_from_cp(y_cp, self.x_cp, n)\n\n        return {\n            \'trajectory\':   final_traj,\n            \'proposal\':     self.proposal(context, n),\n            \'history\':      history,\n            \'energy_curve\': energy_curve,\n            \'y_cp_final\':   y_cp,\n        }\n\n    def settle_with_snapshots(self, context: np.ndarray = OBS_CENTRES,\n                              n: int = SEQ_LEN,\n                              n_steps: int = 100,\n                              lr: float = 0.025,\n                              noise_std: float = 0.30,\n                              rng: np.random.Generator = None) -> dict:\n        """Dense history (every iteration) for Fig 3 and animation."""\n        return self.settle(context, n, n_steps, lr, noise_std, rng, record_every=1)\n'
    inference_module = _install_module("inference", _inference_source, str(fake_code_dir / "inference.py"))
    _figures_fixed_source = '"""\nfigures_fixed.py\n================\nCorrected publication plotting code for the three JMLR figures that needed\nvisual cleanup:\n\n  Figure 2  -> mean_collapse.{pdf,png}\n  Figure 4  -> geometric_environment.{pdf,png}\n  Figure 12 -> geometric_ambiguity_sweep.{pdf,png}\n\nThe scientific computations are unchanged.  This file only changes figure\nstyling, color semantics, label placement, legend placement, and plotting\nz-order to remove overlaps and improve readability in print/PDF.\n\nColor semantics used consistently:\n  * Valid Mode A / Settling: green\n  * Valid Mode B: blue\n  * Invalid mean / collision: red\n  * Obstacles / safety margins: neutral charcoal / light gray\n"""\n\nfrom pathlib import Path\nimport numpy as np\nimport matplotlib\nmatplotlib.use("Agg")\nimport matplotlib.pyplot as plt\nfrom matplotlib.lines import Line2D\nfrom matplotlib.patches import Patch\n\nfrom environment import (\n    OBS_CENTRES, OBS_RADIUS, OBS_R, START, GOAL, SEQ_LEN,\n    upper_trajectory, lower_trajectory, is_collision_free, _bump,\n)\nfrom inference import attention_inference, SettlingInferenceModule\n\nOUT_DIR = Path(__file__).resolve().parent.parent / "figures"\nOUT_DIR.mkdir(parents=True, exist_ok=True)\n\n# -----------------------------------------------------------------------------\n# Color palette: semantic, print-friendly, and intentionally non-confusing.\n# ----------------------------------------------------------------------------_\nVALID_A = "#2E8B57"      # green: valid Mode A / safe / Settling\nVALID_B = "#2F6FB0"      # blue: valid Mode B\nINVALID = "#C43C39"      # red: invalid mean / collision only\nSETTLING = "#2E8B57"     # same semantic green\nATTENTION = "#C43C39"    # mean-seeking failure in these diagnostics\nOBSTACLE_CORE = "#3F3F3F"\nOBSTACLE_MARGIN = "#D9D9D9"\nNEUTRAL = "#5A5A5A"\nGRID = "#D0D0D0"\nBOUNDARY = "#7A7A7A"\n\nplt.rcParams.update({\n    "font.family": "serif",\n    "font.size": 10.5,\n    "axes.titlesize": 12,\n    "axes.labelsize": 10.5,\n    "legend.fontsize": 8.5,\n    "xtick.labelsize": 9.5,\n    "ytick.labelsize": 9.5,\n    "figure.dpi": 150,\n    "savefig.dpi": 300,\n    "savefig.bbox": "tight",\n    "axes.spines.top": False,\n    "axes.spines.right": False,\n})\n\n\ndef _save(fig, stem: str):\n    for ext in ("pdf", "png"):\n        fig.savefig(OUT_DIR / f"{stem}.{ext}", bbox_inches="tight")\n    plt.close(fig)\n    print(f"saved: {stem}.pdf / {stem}.png")\n\n\ndef _draw_obstacles(ax, show_labels=True):\n    """Draw obstacles without duplicating legend entries."""\n    for i, (cx, cy) in enumerate(OBS_CENTRES):\n        ax.add_patch(\n            plt.Circle(\n                (cx, cy), OBS_R,\n                facecolor=OBSTACLE_MARGIN,\n                edgecolor="#BFBFBF",\n                linewidth=0.8,\n                alpha=0.72,\n                zorder=2,\n            )\n        )\n        ax.add_patch(\n            plt.Circle(\n                (cx, cy), OBS_RADIUS,\n                facecolor=OBSTACLE_CORE,\n                edgecolor="#222222",\n                linewidth=1.0,\n                alpha=0.98,\n                zorder=3,\n            )\n        )\n        if show_labels:\n            ax.text(\n                cx, cy, f"Obs {i+1}",\n                ha="center", va="center",\n                color="white", fontsize=8.2,\n                fontweight="bold", zorder=6,\n            )\n\n    # Neutral start + green goal; labels are offset so they never overlap points.\n    ax.scatter(*START, s=90, color="white", edgecolors="#222222",\n               linewidths=1.2, marker="o", zorder=8)\n    ax.scatter(*GOAL, s=150, color=VALID_A, edgecolors="#222222",\n               linewidths=1.0, marker="*", zorder=8)\n\n    ax.annotate(\n        "Start", xy=START, xytext=(8, 14), textcoords="offset points",\n        ha="left", va="bottom", color=NEUTRAL, fontsize=8.5, zorder=9,\n    )\n    ax.annotate(\n        "Goal", xy=GOAL, xytext=(-8, 14), textcoords="offset points",\n        ha="right", va="bottom", color=VALID_A, fontsize=8.5,\n        fontweight="bold", zorder=9,\n    )\n\n    ax.set_xlim(-1.20, 1.20)\n    ax.set_ylim(-1.05, 1.05)\n    ax.set_aspect("equal")\n    ax.grid(True, alpha=0.32, color=GRID, linewidth=0.55, zorder=0)\n    ax.set_xlabel("x  (inference state)")\n    ax.set_ylabel("y  (inference state)")\n\n\ndef figure2_mean_collapse():\n    """Corrected Figure 2: no legend/annotation overlap, semantic colors."""\n    u = upper_trajectory(SEQ_LEN)\n    l = lower_trajectory(SEQ_LEN)\n    m = attention_inference()\n\n    fig, (ax, ax2) = plt.subplots(\n        1, 2, figsize=(11.6, 4.8),\n        gridspec_kw={"width_ratios": [2.05, 1.0]},\n        constrained_layout=True,\n    )\n\n    _draw_obstacles(ax, show_labels=False)\n\n    ax.plot(u[:, 0], u[:, 1], color=VALID_A, lw=2.8, zorder=5)\n    ax.plot(l[:, 0], l[:, 1], color=VALID_B, lw=2.8, zorder=5)\n    ax.plot(m[:, 0], m[:, 1], color=INVALID, lw=2.6, ls="--", zorder=6)\n\n    # Collision markers and small labels are separated from the curves/legend.\n    for cx, cy in OBS_CENTRES:\n        ax.scatter(cx, cy, s=165, color=INVALID, marker="X",\n                   edgecolors="#222222", linewidths=0.8, zorder=9)\n        ax.annotate(\n            "collision", xy=(cx, cy), xytext=(0, 24),\n            textcoords="offset points", ha="center", va="bottom",\n            fontsize=8.2, color=INVALID, fontweight="bold",\n            arrowprops=dict(arrowstyle="-|>", lw=0.9, color=INVALID,\n                            shrinkA=3, shrinkB=5),\n            zorder=10,\n        )\n\n    ax.set_title(\n        "Conditional mean collapse\\n"\n        r"$f^*(c)=\\mathbb{E}[y\\mid c]=\\bar{y}\\notin\\mathcal{V}(c)$",\n        fontweight="bold",\n    )\n\n    # Right cross-section: keep all labels out of the data region.\n    ax2.axhspan(-OBS_R, OBS_R, color=OBSTACLE_MARGIN, alpha=0.85, zorder=1)\n    ax2.axhline(0.72, color=VALID_A, lw=2.7, zorder=3)\n    ax2.axhline(-0.72, color=VALID_B, lw=2.7, zorder=3)\n    ax2.axhline(0.0, color=INVALID, lw=2.6, ls="--", zorder=4)\n    ax2.set_xlim(-0.5, 1.5)\n    ax2.set_ylim(-1.05, 1.05)\n    ax2.set_xticks([])\n    ax2.set_ylabel("y at obstacle midplane  (x = 0)")\n    ax2.set_title("Symmetric cross-section at x = 0", fontweight="bold")\n    ax2.grid(False)\n\n    # One shared figure legend, below the panels; no overlap with data.\n    handles = [\n        Line2D([0], [0], color=VALID_A, lw=2.8, label="Valid Mode A (upper)"),\n        Line2D([0], [0], color=VALID_B, lw=2.8, label="Valid Mode B (lower)"),\n        Line2D([0], [0], color=INVALID, lw=2.6, ls="--", label="Conditional mean (invalid)"),\n        Patch(facecolor=OBSTACLE_MARGIN, edgecolor="#BFBFBF", label="Obstacle / safety zone"),\n    ]\n    fig.legend(\n        handles=handles, loc="lower center", bbox_to_anchor=(0.5, -0.035),\n        ncol=4, frameon=False, columnspacing=1.6, handlelength=2.7,\n    )\n\n    fig.suptitle(\n        "Conditional Mean Collapse in a Non-Convex Validity Space",\n        fontsize=14.2, fontweight="bold",\n    )\n    _save(fig, "mean_collapse")\n\n\ndef figure4_geometric_environment():\n    """Corrected Figure 4: visible green/blue valid regions and clean labels."""\n    fig, ax = plt.subplots(figsize=(8.2, 5.0), constrained_layout=True)\n    _draw_obstacles(ax, show_labels=True)\n\n    upper = upper_trajectory()\n    lower = lower_trajectory()\n    xs = np.linspace(-1.0, 1.0, 300)\n    y_up = _bump(xs, -0.4, 0.38, 0.72) + _bump(xs, 0.4, 0.38, 0.72)\n    y_low = -y_up\n\n    # Stronger, color-preserving valid-region fills.  No gray valid regions.\n    ax.fill_between(\n        xs, np.minimum(y_up + 0.16, 1.0), 1.0,\n        facecolor=VALID_A, alpha=0.12, edgecolor="none", zorder=1,\n    )\n    ax.fill_between(\n        xs, -1.0, np.maximum(y_low - 0.16, -1.0),\n        facecolor=VALID_B, alpha=0.12, edgecolor="none", zorder=1,\n    )\n\n    # Invalid central region: red is reserved only for invalidity.\n    ax.axhspan(-OBS_R, OBS_R, facecolor=INVALID, alpha=0.075, zorder=1)\n    ax.axhline(0.0, color=INVALID, lw=1.45, ls="--", alpha=0.90, zorder=4)\n\n    ax.plot(upper[:, 0], upper[:, 1], color=VALID_A, lw=2.8, zorder=5)\n    ax.plot(lower[:, 0], lower[:, 1], color=VALID_B, lw=2.8, zorder=5)\n\n    # Region labels in blank space, not on the trajectories.\n    ax.text(\n        0.0, 0.96, "Valid region A",\n        ha="center", va="top", color=VALID_A, fontsize=9.3,\n        fontweight="bold", fontstyle="italic", zorder=7,\n    )\n    ax.text(\n        0.0, -0.96, "Valid region B",\n        ha="center", va="bottom", color=VALID_B, fontsize=9.3,\n        fontweight="bold", fontstyle="italic", zorder=7,\n    )\n    ax.annotate(\n        "Invalid mean region",\n        xy=(0.0, 0.0), xytext=(0.0, 0.34),\n        ha="center", va="bottom", fontsize=8.2, color=INVALID,\n        arrowprops=dict(arrowstyle="->", color=INVALID, lw=0.9), zorder=8,\n    )\n\n    handles = [\n        Line2D([0], [0], color=VALID_A, lw=2.8, label="Valid Mode A (upper)"),\n        Line2D([0], [0], color=VALID_B, lw=2.8, label="Valid Mode B (lower)"),\n        Line2D([0], [0], color=INVALID, lw=1.6, ls="--", label="Invalid conditional mean"),\n        Patch(facecolor=INVALID, edgecolor="none", alpha=0.18, label="Invalid mean region"),\n    ]\n    ax.legend(\n        handles=handles, loc="lower center", bbox_to_anchor=(0.5, -0.23),\n        ncol=2, frameon=False, columnspacing=2.0, handlelength=3.0,\n    )\n\n    ax.set_title(\n        "Controlled Non-Convex Validity Environment\\n"\n        "Two designated valid trajectory modes and an invalid mean region",\n        fontweight="bold",\n    )\n    _save(fig, "geometric_environment")\n\n\ndef _compute_ambiguity_sweep():\n    """Use the same sweep logic as the supplied code; no scientific change."""\n    rng = np.random.default_rng(17)\n    sbi = SettlingInferenceModule()\n    alphas = np.linspace(0.0, 0.5, 30)\n\n    mean_col, settle_col, settle_commit = [], [], []\n    for alpha in alphas:\n        obs = OBS_CENTRES.copy()\n        obs[:, 1] = alpha\n\n        x = np.linspace(-1.0, 1.0, SEQ_LEN)\n        y_upper = (\n            _bump(x, -0.4, 0.38, 0.72 + alpha)\n            + _bump(x, 0.4, 0.38, 0.72 + alpha)\n        )\n        upper = np.column_stack([x, y_upper])\n\n        y_lower = -(\n            _bump(x, -0.4, 0.38, 0.72 - alpha)\n            + _bump(x, 0.4, 0.38, 0.72 - alpha)\n        )\n        lower = np.column_stack([x, y_lower])\n\n        mean_traj = 0.5 * (upper + lower)\n        mean_col.append(0.0 if is_collision_free(mean_traj, obs) else 1.0)\n\n        result = sbi.settle(context=obs, n_steps=100, rng=rng)\n        settle_col.append(\n            0.0 if is_collision_free(result["trajectory"], obs) else 1.0\n        )\n        mid_y = result["trajectory"][SEQ_LEN // 2, 1]\n        settle_commit.append(float(abs(mid_y) > 0.15))\n\n    return alphas, np.asarray(mean_col), np.asarray(settle_col), np.asarray(settle_commit)\n\n\ndef figure12_geometric_ambiguity_sweep():\n    """Corrected Figure 12: legends and first points no longer overlap."""\n    alphas, mean_col, settle_col, settle_commit = _compute_ambiguity_sweep()\n\n    fig, (ax1, ax2) = plt.subplots(\n        1, 2, figsize=(12.4, 4.75), constrained_layout=True\n    )\n\n    # Left: draw reference line behind markers and give x=0 breathing room.\n    ax1.axvline(0.0, color=BOUNDARY, ls=":", lw=1.35, alpha=0.55, zorder=1)\n    ax1.plot(\n        alphas, mean_col, color=ATTENTION, lw=2.35, marker="o", ms=4.2,\n        markerfacecolor="white", markeredgewidth=1.2, zorder=4,\n        label="Mean-seeking collision rate",\n    )\n    ax1.plot(\n        alphas, settle_col, color=SETTLING, lw=2.35, marker="s", ms=4.0,\n        zorder=5, label="Settling collision rate",\n    )\n    ax1.annotate(\n        "maximum ambiguity", xy=(0.0, 0.52), xytext=(0.045, 0.52),\n        textcoords="data", ha="left", va="center", fontsize=8.2,\n        color=BOUNDARY,\n        arrowprops=dict(arrowstyle="->", color=BOUNDARY, lw=0.8),\n    )\n    ax1.set_xlim(-0.025, 0.525)\n    ax1.set_ylim(-0.06, 1.10)\n    ax1.set_xlabel(r"Ambiguity $\\alpha$  (obstacle y-offset)")\n    ax1.set_ylabel("Collision rate")\n    ax1.set_title("Collision Rate Across the Controlled Sweep", fontweight="bold")\n    ax1.grid(True, alpha=0.25, color=GRID, linewidth=0.55)\n    ax1.legend(\n        loc="lower center", bbox_to_anchor=(0.5, -0.25),\n        ncol=2, frameon=False, handlelength=2.6,\n    )\n\n    # Right: keep the reference boundary behind data; no shaded block or red region.\n    ax2.axhline(\n        0.0, color=NEUTRAL, lw=1.8, ls="--", alpha=0.85, zorder=1,\n        label="Mean-seeking: no commitment",\n    )\n    ax2.axvline(0.12, color=BOUNDARY, ls=":", lw=1.35, alpha=0.55, zorder=1)\n    ax2.plot(\n        alphas, settle_commit, color=SETTLING, lw=2.35, marker="D", ms=4.0,\n        zorder=5, label="Settling commitment indicator",\n    )\n    ax2.annotate(\n        "reference regime boundary", xy=(0.12, 1.02), xytext=(0.155, 1.10),\n        ha="left", va="center", fontsize=8.2, color=BOUNDARY,\n        arrowprops=dict(arrowstyle="->", color=BOUNDARY, lw=0.8),\n    )\n    ax2.set_xlim(-0.025, 0.525)\n    ax2.set_ylim(-0.08, 1.18)\n    ax2.set_xlabel(r"Ambiguity $\\alpha$")\n    ax2.set_ylabel("Commitment indicator")\n    ax2.set_title("Settling Commitment Under the Same Sweep", fontweight="bold")\n    ax2.grid(True, alpha=0.25, color=GRID, linewidth=0.55)\n    ax2.legend(\n        loc="lower center", bbox_to_anchor=(0.5, -0.25),\n        ncol=2, frameon=False, handlelength=2.6,\n    )\n\n    fig.suptitle(\n        "Controlled Ambiguity Sweep: Mean-Seeking vs. Settling",\n        fontsize=14.0, fontweight="bold",\n    )\n    _save(fig, "geometric_ambiguity_sweep")\n\n\ndef main():\n    figure2_mean_collapse()\n    figure4_geometric_environment()\n    figure12_geometric_ambiguity_sweep()\n\n\nif __name__ == "__main__":\n    main()\n'
    figures_fixed_module = _install_module("figures_fixed", _figures_fixed_source, str(fake_code_dir / "figures_fixed.py"))

